import {h,table,details,f,field} from './dom.mjs';
import {store,commit,setUi,switchStage} from './state.mjs';
import {displayRunOrder,shortRunLabel,shortLabelSession} from '../data-model/workspaces.mjs';
import {prepareCompoundWorkspace} from '../data-model/compound-workflow.mjs';
import {evaluateSession} from '../decision/evaluate.mjs';
import {isBlank,t0Of} from '../data-model/derive.mjs';
import {downloadText} from './library.mjs';
import {lineageCompare} from '../retention/eligibility.mjs';

export function dashboardCompoundModel(s,own=evaluateSession(s).retention){
 const other=store.workspaces.retention,current=s.runs.find(r=>r.id===s.settings.course?.currentRunId)||s.runs.filter(r=>!isBlank(r)).at(-1),ownRef=own.eligibility?.reference;
 if(own.status==='model-ready'&&current&&ownRef&&lineageCompare(s,s.settings,current,ownRef).comparable)return {analysis:own,session:s,origin:'Imported Dashboard CSV records'};
 const a=evaluateSession(shortLabelSession(other)).retention,ref=a.eligibility?.reference;
 if(a.status==='model-ready'&&current&&ref&&lineageCompare(s,s.settings,current,ref).comparable)return {analysis:a,session:other,origin:'Compatible explicit Retention analysis (original Dashboard records unchanged)'};
 return {analysis:own.status==='model-ready'?{...own,issued:null,intermediate:null,reasons:['The fitted model is not comparable with the selected current run. No result is transferred across sample, column, solvent or temperature changes.']}:own,session:s,origin:'Imported Dashboard CSV records'};
}
export function dashboardCompoundResults(s,prepared=dashboardCompoundModel(s)){const {analysis:a,session,origin}=prepared,result=a.issued&&a.intermediate?.ok&&a.fits?.coverage?.complete,lines=a.steps?.fits||[],runs=(a.eligibility?.runs||[]).filter(x=>x.eligible).map(x=>x.run);
 return h('section',{class:'card','data-testid':'dashboard-compound-results'},h('h3','Automatic all-compound results'),h('p',{class:'small'},'Recomputed from imported, explicitly labelled compounds; no Calculate button or manual analysis copy is needed. Peak order and R² never identify a compound. Predictions are not measured separation or injection clearance.'),
 result?h('div',{'data-testid':'dashboard-compound-output'},h('p',h('strong',`Intermediate ${a.intermediate.best.B} %B`),` · predicted latest tR ${f(a.intermediate.best.lastTR,3)} min · smallest adjacent alpha ${f(a.intermediate.best.minAlpha,3)} (${a.intermediate.best.pair.join(' / ')}). ${a.intermediate.note||''}`),h('p',`Minimum ${a.issued.candidates.minimum?.B??'not established'} %B. Origin: ${origin}. Source runs: ${runs.map(shortRunLabel).join(', ')}.`),h('p',{class:'small'},'Intermediate maximises the smallest adjacent alpha within the searched range. It does not predict peak widths, Rs, pressure or the best experimental method.'),table(['Compound','log k intercept','Slope per %B','R²'],lines.map(x=>h('tr',h('td',x.compound),h('td',f(x.intercept,6)),h('td',f(x.slope,6)),h('td',f(x.r2,6)))))):
 h('p',{'data-testid':'dashboard-compound-blockers',class:'small'},s.runs.length?`No whole-sample intermediate issued. ${[...(a.reasons||[]),...(a.missing||[])].slice(0,3).join(' ')||'Comparable runs, file-stated compound labels, sample identity and a usable t0 basis are not yet established.'} The last-peak fit below is a different model.`:'Import your own Retention CSVs as they are acquired. Missing compound labels or t0 do not block ordinary first-run analysis.'),
 result?h('p',{class:'tiny'},`Coverage: ${a.fits.coverage.adequate}/${a.fits.coverage.expected} defined analytes. ${session===s?'No analysis copies created.':'Separate analysis inputs retained.'}`):null);
}

function jump(id){const el=document.querySelector(`[data-testid="${id}"]`);let d=el?.closest('details');while(d){d.open=true;d=d.parentElement?.closest('details');}el?.scrollIntoView({block:'start',behavior:'smooth'});}
function openModel(){if(store.ui.importBusy||store.ui.pendingGeneric?.length)return;switchStage('retention');setUi(u=>{u.advancedCompoundOpen=true;u.compoundGuideOpen=true;u.libraryAdvanced=true;});jump('compound-guided-steps');}
export function compoundBridge(s){
 const dst=store.workspaces.retention,model=evaluateSession(shortLabelSession(dst)).retention;
 const rows=displayRunOrder(s.runs.filter(r=>!isBlank(r)&&r.conditions.mode?.value==='ISO'),s),selected=new Set(store.ui.compoundBridgeIds||[]);
 return details('Optional · All-compound intermediate model',false,h('section',{class:'card','data-testid':'compound-model-bridge'},h('h3','From imported CSVs to an all-compound model'),
 h('p',{class:'small'},'Use this only for predictions across identified compounds. The ordinary last-peak workflow still works without it. Select comparable isocratic runs, then open the guided model. A higher R² or equal peak count does not establish compound identity.'),
 h('p',{'data-testid':'compound-bridge-status'},`Analysis workspace: ${dst.runs.length} run(s); ${model.status}. ${model.fits?.coverage?`${model.fits.coverage.adequate}/${model.fits.coverage.expected} defined analytes adequately modelled.`:'No all-compound output established.'}`),
 table(['Use for analysis','Measured run','Recorded method','Existing analysis'],rows.map(r=>h('tr',h('td',h('input',{type:'checkbox',checked:selected.has(r.id),'data-testid':'compound-source-'+r.id,onchange:e=>setUi(u=>{const ids=new Set(u.compoundBridgeIds||[]);e.target.checked?ids.add(r.id):ids.delete(r.id);u.compoundBridgeIds=[...ids];})})),h('td',shortRunLabel(r)),h('td',`${r.conditions.organic?.value??'?'} ${r.conditions.percentB?.value??'?'} %B · ${r.conditions.ovenSetpoint?.value??'?'} °C`),h('td',dst.runs.some(x=>x.id===r.id)?'Already present; will not be overwritten':'Not copied')))),
 h('button',{type:'button','data-testid':'compound-prepare',disabled:!rows.some(r=>selected.has(r.id)),onclick:()=>{let result;commit(()=>{result=prepareCompoundWorkspace(store.workspaces,rows.filter(r=>selected.has(r.id)).map(r=>r.id));});if(result.ok)openModel();setUi(u=>{u.message=result.reason;});}},'Use selected runs / open guided model'),
 h('button',{type:'button','data-testid':'compound-open-existing',onclick:openModel},dst.runs.length?'Continue existing compound model':'Open empty guided model'),
 h('p',{class:'tiny'},'This explicit action adds independent analysis copies, marks only newly copied runs for fitting, and copies Dashboard specifications only into an empty analysis workspace. No run is moved, no existing analysis is replaced, and changing its model does not alter the Dashboard original. Reconcile scientific changes explicitly; the Dashboard does not silently prefer an edited analysis copy.')));
}
export function compoundGuide(st){
 if(!st.ui.compoundGuideOpen)return null;
 const s=st.session,a=st.evaluation.retention,runs=displayRunOrder(s.runs.filter(r=>r.flags.fit),s),nB=new Set(runs.map(r=>r.conditions.percentB?.value).filter(Number.isFinite)).size,review=runs.find(r=>r.id===st.ui.compoundGuideRunId)||runs[0];
 const reveal=id=>{setUi(u=>{u.advancedCompoundOpen=true;u.libraryAdvanced=true;});jump(id);};
 return h('section',{class:'card','data-testid':'compound-guided-steps'},h('h3','Guided all-compound model · no identities guessed'),
 runs.length?field('Analysis run to review in steps 2 and 4',h('select',{'data-testid':'compound-guide-run',onchange:e=>setUi(u=>{u.compoundGuideRunId=e.target.value;})},runs.map(r=>h('option',{value:r.id,selected:r.id===review.id?'selected':null},shortRunLabel(r))))):null,
 h('ol',h('li',`${runs.length} selected fit runs at ${nB} distinct %B values. Keep solvent, temperature, sample and physical column comparable; the eligibility checks below explain every exclusion.`,h('button',{type:'button','data-testid':'compound-guide-runs',onclick:()=>reveal('run-table')},'1. Review fit runs / recorded conditions')),
 h('li',`${runs.filter(r=>t0Of(s,r,s.settings).ok).length}/${runs.length} selected runs have a usable t0 basis. Use a documented value, confirmed marker or explicitly labelled permitted estimate; do not identify the first peak automatically.`,h('button',{type:'button','data-testid':'compound-guide-t0',disabled:!review,onclick:()=>{setUi(u=>{u.detailRunId=review.id;u.detailTab='marker';});jump('run-detail');}},`2. Review t0${review?' · '+shortRunLabel(review):''}`)),
 h('li',`${s.compounds.filter(c=>c.role==='analyte').length} analytes defined. Define compounds from your sample record; loading the course list does not assign their peaks.`,h('button',{type:'button','data-testid':'compound-guide-compounds',onclick:()=>reveal('compounds')},'3. Define compounds')),
 h('li','Assign the same compounds in every fit run using standards or other recorded evidence. Position and AUC alone are not proof. Choose each run above to review it.',h('button',{type:'button','data-testid':'compound-guide-identities',disabled:!review,onclick:()=>{setUi(u=>{u.detailRunId=review.id;u.detailTab='peaks';});jump('run-detail');}},`4. Assign peaks / identities${review?' · '+shortRunLabel(review):''}`)),
 h('li','Fits, residuals, all-analyte coverage and intermediate candidates recalculate after each recorded change. An unresolved or deficient model issues no whole-sample recommendation.',h('button',{type:'button','data-testid':'compound-guide-result',onclick:()=>reveal('retention-steps')},'5. Review automatic results / blockers'))),
 h('p',{'data-testid':'compound-guided-status'},`Current result: ${a.status}. ${a.fits?.coverage?`${a.fits.coverage.adequate}/${a.fits.coverage.expected} defined analytes adequately modelled.`:'No confirmed all-compound fit yet.'}`),
 a.intermediate?.ok&&a.status==='model-ready'?h('p',{'data-testid':'compound-guided-result'},`MODEL OUTPUT, not a measured result: intermediate ${a.intermediate.best.B} %B; predicted last tR ${f(a.intermediate.best.lastTR,3)} min; smallest adjacent alpha ${f(a.intermediate.best.minAlpha,3)}. Source runs: ${runs.map(shortRunLabel).join(', ')}. Verify model scope and hardware before execution.`):h('div',h('p',{class:'small warn','data-testid':'compound-guided-blockers'},'No whole-sample intermediate issued. Follow the numbered checks above; excluded runs, missing assignments and fit-quality failures remain unresolved until supported by evidence. Open the reasons below for the corresponding run.'),details('Why each analysis run is excluded / full model blockers',false,table(['Analysis run','Eligibility','Run-specific grounds'],(a.eligibility?.runs||[]).map(x=>h('tr',h('td',x.label),h('td',x.eligible?'Eligible':'Excluded'),h('td',x.reasons.join('; ')||'No eligibility exclusion')))),h('ul',[...new Set([...a.reasons,...a.missing])].map(x=>h('li',{class:'small'},x))))),
 h('button',{type:'button','data-testid':'compound-guide-export',onclick:()=>downloadText('all-compound-model-evidence.json',JSON.stringify({analysis:a,sourceRuns:runs.map(r=>({id:r.id,label:shortRunLabel(r),rawSha256:r.raw.sha256})),planningOnly:true,performed:false},null,2),'application/json')},'Export current compound-model results / blockers'),
 h('p',{class:'tiny'},'This is a separate analysis workspace, not a new experiment or a substitute for the active Dashboard action. Return using Dashboard · Cycle 1–4; original imports and Selectivity history remain there.'));
}
